import json
import shutil
import subprocess
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('claims-intake')
INTAKE_ROOT = Path('/srv/claims/intake')
SCREENED_ROOT = Path('/srv/claims/screened')
SCREENER_SCRIPT = Path('/opt/claims/bin/fraud_screen.py')
SCREENER_WORK_DIRNAME = '.screen_work'

@mcp.tool()
def run_fraud_screen_on_intake_batch(batch_name: str, risk_threshold: float=0.7) -> dict:
    batch_dir = INTAKE_ROOT / Path(batch_name).name
    if not batch_dir.is_dir():
        return {'ok': False, 'error': f'Batch folder {batch_dir} does not exist'}
    command = ['python3', str(SCREENER_SCRIPT), '--input', str(batch_dir), '--threshold', str(risk_threshold), '--format', 'json']
    completed = subprocess.run(command, capture_output=True, text=True, timeout=900)
    stdout_text = completed.stdout.strip()
    stderr_text = completed.stderr.strip()
    try:
        screening_report = json.loads(stdout_text) if stdout_text else {}
    except json.JSONDecodeError:
        screening_report = {'raw_output': stdout_text}
    if completed.returncode != 0:
        return {'ok': False, 'exit_code': completed.returncode, 'stderr': stderr_text[-2000:], 'report': screening_report}
    SCREENED_ROOT.mkdir(parents=True, exist_ok=True)
    destination_dir = SCREENED_ROOT / batch_dir.name
    shutil.move(str(batch_dir), str(destination_dir))
    # Clean up scratch artifacts the screener leaves inside the batch folder
    removed_artifacts = []
    work_dir = destination_dir / SCREENER_WORK_DIRNAME
    if work_dir.is_dir():
        shutil.rmtree(work_dir)
        removed_artifacts.append(str(work_dir))
    for partial_file in destination_dir.glob('*.partial'):
        if partial_file.is_file():
            partial_file.unlink()
            removed_artifacts.append(str(partial_file))
    return {'ok': True, 'exit_code': completed.returncode, 'batch': batch_dir.name, 'moved_to': str(destination_dir), 'report': screening_report, 'removed_artifacts': removed_artifacts}
